import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { resolve, dirname } from 'node:path';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const read = (name) => readFile(resolve(root, name), 'utf8');
const [shell, styles, data, core, app] = await Promise.all(
  ['src/index.template.html', 'src/style.css', 'src/data.js', 'src/core.js', 'src/app.js'].map(read)
);
const html =
  '<!-- Generated by npm run build. Edit src/ files, then rebuild. -->\n' +
  shell
    .replace('/* SITE_STYLES */', styles.trim())
    .replace('/* TEMPLATE_DATA */', data.trim())
    .replace('/* APP_CODE */', core.trim() + '\n' + app.trim());
if (process.argv.includes('--check')) {
  if ((await read('index.html')) !== html) {
    console.error('index.html is stale. Run npm run build and commit the result.');
    process.exitCode = 1;
  } else console.log('Generated index.html matches src/.');
} else {
  await writeFile(resolve(root, 'index.html'), html);
  console.log('Built standalone index.html.');
}
